@Service
@Transactional
public class LoanUnderwritingService {

    private final LoanRepository loanRepository;
    private final AIUnderwritingClient aiClient;
    private final DocumentService documentService;
    private final EventPublisher eventPublisher;

    @Autowired
    public LoanUnderwritingService(
        LoanRepository loanRepository,
        AIUnderwritingClient aiClient,
        DocumentService documentService,
        EventPublisher eventPublisher
    ) {
        this.loanRepository = loanRepository;
        this.aiClient = aiClient;
        this.documentService = documentService;
        this.eventPublisher = eventPublisher;
    }

    public UnderwritingResult submitForUnderwriting(String loanId) {
        Loan loan = loanRepository.findById(loanId)
            .orElseThrow(() -> new LoanNotFoundException(loanId));

        if (!loan.isReadyForUnderwriting()) {
            throw new InvalidLoanStateException("Loan not ready for underwriting");
        }

        List<Document> documents = documentService.getVerifiedDocuments(loanId);
        LoanData loanData = extractLoanData(loan, documents);

        UnderwritingDecision decision = aiClient.evaluateLoan(loanData);

        loan.setUnderwritingDecision(decision);
        loan.setStatus(mapDecisionToStatus(decision));
        loan.setLastModifiedDate(Instant.now());

        loanRepository.save(loan);

        eventPublisher.publish(new UnderwritingCompletedEvent(loanId, decision));

        return UnderwritingResult.builder()
            .loanId(loanId)
            .decision(decision)
            .timestamp(Instant.now())
            .build();
    }

    private LoanStatus mapDecisionToStatus(UnderwritingDecision decision) {
        return switch (decision.getDecision()) {
            case APPROVED -> LoanStatus.APPROVED;
            case CONDITIONAL_APPROVAL -> LoanStatus.CONDITIONAL_APPROVAL;
            case REFERRED -> LoanStatus.MANUAL_REVIEW;
            case DECLINED -> LoanStatus.DECLINED;
        };
    }
}

