@RestController
@RequestMapping("/api/v1/loans")
@Validated
public class LoanController {

    private final LoanService loanService;
    private final LoanValidator loanValidator;

    @Autowired
    public LoanController(LoanService loanService, LoanValidator loanValidator) {
        this.loanService = loanService;
        this.loanValidator = loanValidator;
    }

    @PostMapping
    public ResponseEntity<LoanResponse> createLoan(
        @Valid @RequestBody LoanRequest request,
        @RequestHeader("X-User-Id") String userId
    ) {
        ValidationResult validation = loanValidator.validate(request);
        if (!validation.isValid()) {
            return ResponseEntity.badRequest()
                .body(LoanResponse.error(validation.getErrors()));
        }

        Loan loan = loanService.createLoan(request, userId);
        return ResponseEntity.status(HttpStatus.CREATED)
            .body(LoanResponse.success(loan));
    }

    @GetMapping("/{loanId}")
    public ResponseEntity<LoanResponse> getLoan(@PathVariable String loanId) {
        return loanService.findById(loanId)
            .map(loan -> ResponseEntity.ok(LoanResponse.success(loan)))
            .orElse(ResponseEntity.notFound().build());
    }

    @PutMapping("/{loanId}/submit")
    public ResponseEntity<UnderwritingResponse> submitForUnderwriting(
        @PathVariable String loanId
    ) {
        UnderwritingResult result = loanService.submitForUnderwriting(loanId);
        return ResponseEntity.ok(UnderwritingResponse.from(result));
    }
}

@Repository
public interface LoanRepository extends JpaRepository<Loan, String> {

    @Query("SELECT l FROM Loan l WHERE l.applicant.id = :applicantId AND l.status IN :statuses")
    List<Loan> findByApplicantIdAndStatusIn(
        @Param("applicantId") String applicantId,
        @Param("statuses") List<LoanStatus> statuses
    );

    @Query(value = """
        SELECT l.* FROM loans l
        JOIN applicants a ON l.applicant_id = a.id
        WHERE l.status = 'PENDING_UNDERWRITING'
        AND l.created_at >= :fromDate
        ORDER BY l.priority DESC, l.created_at ASC
        """, nativeQuery = true)
    List<Loan> findPendingUnderwritingLoans(@Param("fromDate") Instant fromDate);

    @Modifying
    @Query("UPDATE Loan l SET l.status = :newStatus WHERE l.id = :loanId")
    int updateLoanStatus(
        @Param("loanId") String loanId,
        @Param("newStatus") LoanStatus newStatus
    );

    @EntityGraph(attributePaths = {"applicant", "documents", "underwritingDecision"})
    Optional<Loan> findByIdWithDetails(String loanId);
}

@Service
public class AIUnderwritingClient {

    private final WebClient webClient;
    private final CircuitBreaker circuitBreaker;

    @Autowired
    public AIUnderwritingClient(
        WebClient.Builder webClientBuilder,
        @Value("${ai.service.url}") String aiServiceUrl,
        CircuitBreakerFactory circuitBreakerFactory
    ) {
        this.webClient = webClientBuilder.baseUrl(aiServiceUrl).build();
        this.circuitBreaker = circuitBreakerFactory.create("ai-underwriting");
    }

    public UnderwritingDecision evaluateLoan(LoanData loanData) {
        return circuitBreaker.run(
            () -> callAIService(loanData),
            throwable -> fallbackDecision(loanData, throwable)
        );
    }

    private UnderwritingDecision callAIService(LoanData loanData) {
        AIRequest request = AIRequest.builder()
            .loanAmount(loanData.getAmount())
            .term(loanData.getTerm())
            .creditScore(loanData.getCreditScore())
            .debtToIncomeRatio(loanData.getDebtToIncomeRatio())
            .collateralValue(loanData.getCollateralValue())
            .build();

        AIResponse response = webClient.post()
            .uri("/evaluate")
            .bodyValue(request)
            .retrieve()
            .bodyToMono(AIResponse.class)
            .timeout(Duration.ofSeconds(30))
            .block();

        return mapToUnderwritingDecision(response);
    }

    private UnderwritingDecision fallbackDecision(LoanData loanData, Throwable error) {
        log.warn("AI service unavailable, routing to manual review", error);
        return UnderwritingDecision.builder()
            .decision(Decision.REFERRED)
            .confidence(0.0f)
            .reason("AI service unavailable - manual review required")
            .build();
    }
}

